head.script:
scwin.labelFormatter = function(itemArr) { //debugger;
    console.log("labelformatter");
    var customArr = itemArr;
    for (var i = 0; i < itemArr.length; i++) {
        customArr[i].label = itemArr[i].label + "커스텀적용아이템";
    }
    return customArr;
}
scwin.selectbox1_onviewchange = function(info) {
    console.log("oldValue##### " + info.oldValue + "  newValue##### " + info.newValue);
    log = "oldValue##### " + info.oldValue + "  newValue##### " + info.newValue;
};
scwin.selectbox1_onchange = function() {
    console.log("onchange");
};
scwin.trigger1_onclick = function(e) { //debugger;
    //selectbox1.setNodeSet('data:dataList3','label','value');
    selectbox1.setNodeSet("response2/vector/data/fruit/");
};
scwin.checkVal = function() {
    return log == "oldValue##### aa1  newValue##### bb1";
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 2번샘플 실행 후 selectbox를 클릭한다.
    //1. After executing sample 2, click on selectbox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 'AA커스텀적용아이템' list가 보여진다.
    //1. A list of 'AA custom items' is displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#selectbox1_itemTable').css('display')", "block");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1_itemTable_2').innerText == 'AA커스텀적용아이템'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_button').click()");
    //Test step 2. 'setnodeset'버튼을 클릭하고 selectbox를 클릭한다.
    //2. Click the 'setnodeset' button and click selectbox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. 'AA1커스텀적용아이템' list가 보여진다.
    //2. The 'AA1 Custom Applied Item' list is displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('#selectbox1_itemTable').css('display')", "block");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1_itemTable_2').innerText == 'AA1커스텀적용아이템'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_button').click()");
    //Test step 3. inputbox에 'aa1'값을 입력하고 enterkey를 실행한다.
    //3. Enter 'aa1' in the inputbox and execute enterkey.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').focus()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('input1').setValue('aa1')");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('input1').blur()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. selectbox에 'AA1커스텀적용아이템'이 보여진다.
    //3. The 'AA1 Custom Applied Item' is displayed in the selectbox.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('selectbox1_label').innerText == 'AA1커스텀적용아이템'", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 4. selectbox에 'BB1커스텀적용아이템'을 선택한다.
    //4. Select 'BB1 Custom Applied Item' in the selectbox.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_button').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('selectbox1_itemTable_3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 4. inputbox에 'bb1'값으로 변경되고 console에 이전값과 이후값이 보여진다. oldValue##### aa1  newValue##### bb1
    //4. The input box is changed to the value 'bb1' and console displays the previous and subsequent values. oldValue ##### aa1 newValue ##### bb1
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('input1').getValue() == 'bb1'", "true");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 12-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
